mapper.select:


    c.del_flag = '0'
     and c.name like concat('%', #{name}, '%')
     and c.source = #{source}
     and c.owner_id = #{ownerId}
     and c.is_public = #{isPublic}

order by c.update_time desc, c.collection_id desc

mapper.update:
update km_collection
name = #{name}, description = #{description}, cover_url = #{coverUrl}, is_public = #{isPublic}, item_count = #{itemCount}, update_by = #{updateBy}, update_time = sysdate()
where collection_id = #{collectionId}

mapper.select:

join km_collection_follow f on f.collection_id = c.collection_id and f.member_id = #{memberId}
where c.del_flag = '0' and c.is_public = '0'
order by f.create_time desc, c.collection_id desc
